WITH event_rows AS (SELECT mktcode,tgtcode,bizdate,ma3>ma30 AND LAG(ma3) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate)<=LAG(ma30) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS matched FROM `newzl`.`hsj_stock_hq_basic_technical`), monthly AS (SELECT mktcode,tgtcode,DATE_TRUNC(bizdate,'MONTH') AS bucket,MAX(CASE WHEN matched THEN 1 ELSE 0 END) AS matched FROM event_rows WHERE bizdate>=DATE_TRUNC('2026-04-14','MONTH') AND bizdate<='2026-04-14' GROUP BY mktcode,tgtcode,DATE_TRUNC(bizdate,'MONTH')), qualified AS (SELECT mktcode,tgtcode FROM monthly GROUP BY mktcode,tgtcode HAVING SUM(matched)=COUNT(*)) SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN qualified q ON q.mktcode=b.mktcode AND q.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14';
